/** Every country, popular ones first. */
export const COUNTRIES: Country[] = [...POPULAR_COUNTRIES, ...OTHER_COUNTRIES];

const BY_CODE = new Map(COUNTRIES.map((c) => [c.code, c]));

/** Is this a country code the search engines will accept? */
export function isCountryCode(code: string | null | undefined): boolean {
  return typeof code === "string" && BY_CODE.has(code.toUpperCase());
}

/**
 * Normalise what a user or an old row gives us.
 *
 * "uk" is the one worth special-casing: it was offered by the keyword
 * research form for a long time, so it is sitting in real databases,
 * and ISO spells the United Kingdom GB.
 */
export function normaliseCountry(code: string | null | undefined): string {
  const upper = String(code ?? "").trim().toUpperCase();
  if (!upper) return "US";
  if (upper === "UK") return "GB";
  return BY_CODE.has(upper) ? upper : "US";
}

/** The display name, or the code back if we do not recognise it. */
export function countryName(code: string): string {
  return BY_CODE.get(normaliseCountry(code))?.name ?? code;
}

/**
 * Markets where the likely language and the search language differ.
 *
 * CLDR answers "what do people speak here", which is not the same
 * question as "what do people type into Google here". In these markets
 * English is the language of business and of most commercial search,
 * so CLDR would say hi/ur/tl and an SEO would say en.
 *
 * Kept deliberately short. Everything not listed uses CLDR.
 */
const SEARCHES_IN_ENGLISH = new Set(["IN", "PK", "NG", "ZA", "PH", "KE", "GH", "SG", "MY"]);

/**
 * The language to ask a search engine for, given a country.
 *
 * Google's autocomplete took `gl` but always `hl=en`, so a German
 * client was asked for German-located results in English. Measured on
 * "zahnarzt" with gl=de: two of the top six suggestions came back as
 * "zahnarzt near me" and "zahnarztpraxis near me" — phrases no German
 * searcher types. With hl=de they are replaced by real ones.
 */
export function languageForCountry(code: string | null | undefined): string {
  const country = normaliseCountry(code);
  if (SEARCHES_IN_ENGLISH.has(country)) return "en";
  try {
    return new Intl.Locale(`und-${country}`).maximize().language || "en";
  } catch {
    return "en";
  }
}
